import sys
sys.path.insert(0, '.')
from durationkit.parse import parse_duration

# Test cases from acceptance criteria
assert parse_duration('90') == 90.0
assert parse_duration(' 90 ') == 90.0
assert parse_duration('0') == 0.0
assert parse_duration('0s') == 0.0
assert parse_duration('2d') == 172800.0
assert parse_duration('3h') == 10800.0
assert parse_duration('15m') == 900.0
assert parse_duration('45s') == 45.0
assert parse_duration('500ms') == 0.5
assert parse_duration('1h30m') == 5400.0
assert parse_duration('2d4h') == 187200.0
assert parse_duration('1m1s') == 61.0
assert parse_duration('1s500ms') == 1.5
assert parse_duration('1d1h1m1s1ms') == 90061.001
assert parse_duration(' 1h 30m ') == 5400.0

# Error cases
try:
    parse_duration('')
except ValueError as e:
    pass
else:
    AssertionError('empty string should raise ValueError')

try:
    parse_duration('   ')
except ValueError as e:
    pass
else:
    AssertionError('whitespace only should raise ValueError')

try:
    parse_duration('-1h')
except ValueError as e:
    pass
else:
    AssertionError('negative number should raise ValueError')

try:
    parse_duration('1.5h')
except ValueError as e:
    pass
else:
    AssertionError('fractional number should raise ValueError')

try:
    parse_duration('1x')
except ValueError as e:
    pass
else:
    AssertionError('unknown unit should raise ValueError')

try:
    parse_duration('1h1h')
except ValueError as e:
    pass
else:
    AssertionError('repeated unit should raise ValueError')

try:
    parse_duration('30m1h')
except ValueError as e:
    pass
else:
    AssertionError('out of order should raise ValueError')

try:
    parse_duration('h')
except ValueError as e:
    pass
else:
    AssertionError('missing number should raise ValueError')

try:
    parse_duration('1h30')
except ValueError as e:
    pass
else:
    AssertionError('number without unit in multi-component should raise ValueError')

try:
    parse_duration('abc')
except ValueError as e:
    pass
else:
    AssertionError('malformed should raise ValueError')

# TypeError
try:
    parse_duration(90)
except TypeError as e:
    pass
else:
    AssertionError('non-string should raise TypeError')

try:
    parse_duration(None)
except TypeError as e:
    pass
else:
    AssertionError('non-string should raise TypeError')

# Return type
assert isinstance(parse_duration('90'), float)
assert isinstance(parse_duration('1h'), float)

